output_text:
[
  {
    "id": "pedestrian_only_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "no_entering_single_file_with_cart",
    "text": "An agent must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "drop_cart_only_at_upper_aisle_mouths",
    "text": "A cart may be put down only at designated upper-aisle mouth parking cells.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "cartParkingBay": {
          "and": [
            "upperAisleMouth",
            "wideCrossAisle"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_upper_shelf_visit",
    "text": "After selecting an item inside a single-file upper aisle, the agent is obliged to retrieve the cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "upperAisleShelfInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "upperAisleShelfInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "wide_shelf_interactions_require_cart",
    "text": "When interacting with shelves from a wide aisle, the agent must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "wideShelfZone": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "wideShelfInteraction": {
          "pre": {
            "and": [
              "wideShelfZone",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_leave_cart_bay_without_cart",
    "text": "After returning to a cart parking bay without the cart, the agent must not move out into the wide store area before retrieving it.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "noCartAtParkingBay": {
          "and": [
            "cartParkingBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "leaveParkingBayWithoutCartToWideArea": {
          "pre": {
            "and": [
              "noCartAtParkingBay",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileShelfAisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveParkingBayWithoutCartToWideArea"
    }
  },
  {
    "id": "cartless_travel_only_in_upper_service_zone",
    "text": "The agent may walk without the cart only within the upper-aisle service zone consisting of a parking bay and its adjacent single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "upperAisleServiceZone": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "upperAisleServiceZone"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westward_travel",
    "text": "Store circulation is one-way, so westward movement is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "westwardMove": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westwardMove"
    }
  }
]
